
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_c_n12_sx_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_c_n12_sx", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.542149981132497e-01, -1.516431290432796e-01, -1.478803524188583e-01, -1.423472982093071e-01, -1.341738238739273e-01, -1.220874775282193e-01, -1.043711315371175e-01, -7.907892130950195e-02, -4.429405523421128e-02, 1.618048826134993e-03, 3.185530928757289e-02, -7.028670545676188e-02, -8.626376481799668e-02, -5.235041364973969e-02, -5.647059013644659e-03, 3.814983425167067e-02, 1.606666136007738e-02, 6.217502413238115e-03, 2.857335079435484e-03, 4.821653001982587e-04]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


